grep -rn "fa-4\.0\|fa-\${" --include="*.yml" --include="*.py" --include="*.sh" --include="*.md" .github bench docs scripts 2>/dev/null | grep -v harbor_fa | head; echo "=== sanity: resolve edge cases ==="; python3 -c "
import sys; sys.path.insert(0,'bench/harbor_fa')
from families import resolve, FamilyError
for s in ['2','2.1','v4','4.0.0','terminal-bench/terminal-bench@4.0.0','terminal-bench/terminal-bench-2@latest']:
    try: print(repr(s), '->', resolve(s))
    except FamilyError as e: print(repr(s), '-> REJECTED')
for s in ['terminal-bench/terminal-bench@latest',' ','',',','terminal-bench/terminal-bench@4.0.0-rc1']:
    try: print(repr(s), '->', resolve(s))
    except FamilyError: print(repr(s), '-> REJECTED')
"

